<template>
  <section class="signature-page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 6 · SIGNED EXIT REVIEW</p><h2>退出复核 Ed25519 签名验证</h2><p>验证三角色外部签名、固定信任策略、当前退出审计哈希和真实项目绑定；系统不生成签名。</p></div><nav><RouterLink to="/story/stage6-exit-audit">退出审计</RouterLink><RouterLink to="/story/stage6-operations">Stage 6 总控</RouterLink></nav></header>
    <div class="truth-lock"><strong>验证签名 ≠ 创建签名</strong><span>Trust policy 独立于 attestation；验证通过也不自动落盘 Stage 6 退出记录，更不等于专业通过。</span></div>
    <p v-if="errorMessage" class="error-banner">{{ errorMessage }}</p>

    <section v-if="workspace" class="trust-bar"><div><span>Trust policy</span><strong>{{ workspace.trust_policy.policy_id }}</strong></div><div><span>状态</span><strong>{{ workspace.trust_policy.status }}</strong></div><div><span>Trusted signers</span><strong>{{ workspace.trust_policy.trusted_signer_count }} / {{ workspace.trust_policy.required_role_count }}</strong></div><label>项目<select v-model="selectedBenchmarkId"><option v-for="project in workspace.projects" :key="project.benchmark_id" :value="project.benchmark_id">{{ project.source_entry }} · candidate {{ project.stage6_exit_candidate?'yes':'no' }}</option></select></label><button :disabled="loading" @click="loadTemplate">生成绑定模板</button><button class="primary" :disabled="loading||!editorText" @click="runInspection">{{ loading?'验证中…':'验证外部签名' }}</button></section>

    <section class="workspace-grid">
      <article class="editor-card"><header><div><p class="eyebrow">ATTESTATION JSON</p><h3>外部签署记录</h3></div><span>仅内存</span></header><div class="toolbar"><label>导入 JSON<input type="file" accept=".json,application/json" @change="importFile"/></label><button @click="copyJson">复制 JSON</button><span>{{ copyMessage }}</span></div><textarea v-model="editorText" aria-label="Stage 6 exit review attestation JSON" spellcheck="false"/><footer><span>{{ editorText.length.toLocaleString() }} 字符</span><b>不签署 · 不导入</b></footer></article>

      <article class="result-card"><header><div><p class="eyebrow">VERIFICATION RESULT</p><h3>信任、绑定与密码学验证</h3></div><b :class="inspection?.signature_verification_ready?'ready':'blocked'">{{ inspection?.signature_verification_ready?'VERIFIED FOR IMPORT':'BLOCKED' }}</b></header>
        <div v-if="inspection" class="metrics"><div><span>Schema</span><strong>{{ inspection.checks.attestation_schema_valid?'合法':'失败' }}</strong></div><div><span>退出候选</span><strong>{{ inspection.checks.stage6_exit_candidate_reverified?'是':'否' }}</strong></div><div><span>已验签</span><strong>{{ inspection.signature_summary.cryptographically_verified_signature_count }}/3</strong></div><div><span>专业通过</span><strong>0</strong></div></div>
        <div v-if="inspection" class="binding-panel"><span>Benchmark <b>{{ inspection.expected_binding.benchmark_id }}</b></span><span>Real project <b>{{ inspection.expected_binding.real_project_id||'未绑定' }}</b></span><span>Audit binding <code>{{ shortHash(inspection.expected_binding.exit_audit_binding_sha256) }}</code></span><span>Attestation payload <code>{{ inspection.canonical_attestation_payload_sha256?shortHash(inspection.canonical_attestation_payload_sha256):'Schema 合法后生成' }}</code></span></div>
        <section v-if="inspection" class="roles"><article><span>编剧 / 编辑</span><strong>{{ inspection.signature_summary.writer_editor_signature_count }}</strong></article><article><span>类型 / 导演</span><strong>{{ inspection.signature_summary.director_signature_count }}</strong></article><article><span>事实 / 文化</span><strong>{{ inspection.signature_summary.fact_culture_reviewer_signature_count }}</strong></article><article><span>Trusted</span><strong>{{ inspection.signature_summary.trusted_signer_count }}</strong></article></section>
        <section v-if="inspection" class="checks"><h4>退出复核签名门禁</h4><div><span v-for="(passed,key) in inspection.checks" :key="key" :class="passed?'ok':'fail'">{{ passed?'✓':'×' }} {{ checkLabel(key) }}</span></div></section>
        <section v-if="inspection?.issues.length" class="issues"><h4>问题 {{ inspection.issues.length }} 项</h4><article v-for="(item,index) in inspection.issues" :key="`${item.code}-${index}`" :class="item.blocking?'blocking':'warning'"><header><b>{{ item.gate.toUpperCase() }}</b><code>{{ item.code }}</code></header><span>{{ item.path||'root' }}</span><p>{{ item.message }}</p></article></section>
        <div class="safety-grid"><span>Signature created <b>否</b></span><span>Attestation persisted <b>否</b></span><span>Exit record persisted <b>否</b></span><span>Execution started <b>否</b></span><span>Professional passed <b>否</b></span></div>
      </article>
    </section>
  </section>
</template>

<script setup lang="ts">
import { onMounted,ref } from 'vue'
import type { Stage6ExitReviewSignatureInspectionResult,Stage6ExitReviewSignatureInspectorWorkspace } from '@shared/types'
import { getStage6ExitReviewSignatureInspector,inspectStage6ExitReviewSignature } from '../api/stage6-revisions'
const workspace=ref<Stage6ExitReviewSignatureInspectorWorkspace|null>(null),inspection=ref<Stage6ExitReviewSignatureInspectionResult|null>(null),selectedBenchmarkId=ref(''),editorText=ref(''),loading=ref(false),errorMessage=ref(''),copyMessage=ref('')
const labels:Record<string,string>={request_valid:'检查请求',json_valid:'JSON 可解析',attestation_schema_valid:'Attestation schema',trust_policy_schema_valid:'Trust policy schema',trust_policy_active:'Trust policy 已激活',stage6_exit_candidate_reverified:'退出候选重验',benchmark_binding_valid:'Benchmark 绑定',real_project_binding_valid:'真实项目绑定',exit_audit_binding_valid:'退出审计哈希绑定',approval_decision_valid:'批准决定',required_roles_signed:'三角色签名齐全',trusted_signer_bindings_valid:'Signer 与信任策略绑定',signed_payload_digests_valid:'签名 Payload Hash',cryptographic_signatures_valid:'Ed25519 验签',signature_timestamps_valid:'签名时间'}
onMounted(loadTemplate)
async function loadTemplate(){loading.value=true;errorMessage.value='';const response=await getStage6ExitReviewSignatureInspector(selectedBenchmarkId.value);loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'签名模板加载失败';return}workspace.value=response.data;selectedBenchmarkId.value=response.data.selected_benchmark_id;editorText.value=response.data.template_raw_json;inspection.value=response.data.template_inspection}
async function runInspection(){loading.value=true;errorMessage.value='';const response=await inspectStage6ExitReviewSignature({raw_json:editorText.value,expected_benchmark_id:selectedBenchmarkId.value});loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'退出复核签名验证失败';return}inspection.value=response.data}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{editorText.value=await file.text();errorMessage.value=''}catch(error){errorMessage.value=`导入失败：${(error as Error).message}`}finally{input.value=''}}
async function copyJson(){try{await navigator.clipboard.writeText(editorText.value);copyMessage.value='已复制'}catch{copyMessage.value='复制未授权'}window.setTimeout(()=>copyMessage.value='',1600)}
function checkLabel(value:string){return labels[value]??value} function shortHash(value:string){return value?`${value.slice(0,10)}…${value.slice(-6)}`:'—'}
</script>

<style scoped>
