.workspace-grid{max-width:1440px;margin:auto;display:grid;grid-template-columns:minmax(420px,.86fr) minmax(570px,1.14fr);gap:15px;align-items:start}.editor-card,.result-card{overflow:hidden;border:1px solid #42516a;border-radius:13px;background:rgba(17,24,35,.96)}.editor-card{position:sticky;top:15px}.editor-card>header,.result-card>header{padding:15px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #344156}.editor-card h3,.result-card h3{margin:3px 0 0}.editor-card header span{color:#7f8a9b;font:10px ui-monospace,monospace}.result-card header>b{font-size:10px;letter-spacing:.07em}.ready{color:#74dbc2}.blocked{color:#ff92a9}.toolbar{padding:10px 13px;display:flex;align-items:center;gap:7px}.toolbar input{display:none}.toolbar span{color:#8490a1;font-size:10px}textarea{width:100%;min-height:650px;padding:16px;box-sizing:border-box;resize:vertical;border:0;border-block:1px solid #2d394c;outline:0;color:#d7dce5;background:#080d14;font:11px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.editor-card footer{padding:10px 13px;display:flex;justify-content:space-between;color:#7e899a;font-size:10px}.editor-card footer b{color:#aac0ec}
.metrics{margin:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.metrics div{padding:9px;border-radius:7px;background:#202a39}.metrics span{display:block;color:#8793a4;font-size:9px}.metrics strong{font-size:15px}.metrics div:last-child strong{color:#ff91a9}.binding-panel,.safety-grid{margin:0 14px 12px;display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.binding-panel span,.safety-grid span{padding:8px;border-radius:7px;color:#8390a1;background:#1c2533;font-size:9px}.binding-panel b,.binding-panel code,.safety-grid b{float:right;max-width:65%;color:#d5dbe5;overflow-wrap:anywhere}.safety-grid b{color:#ff94aa}.roles{margin:0 14px 12px;display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.roles article{padding:8px;border-radius:7px;background:#202a38}.roles span{display:block;color:#8793a3;font-size:8px}.roles strong{font-size:17px}.checks,.issues{margin:0 14px 13px}.checks h4,.issues h4{margin:0 0 7px}.checks>div{display:grid;grid-template-columns:repeat(2,1fr);gap:5px}.checks span{padding:7px;border-radius:6px;font-size:9px}.ok{color:#74d7c0;background:#14362f}.fail{color:#ee96aa;background:#361b27}.issues>article{margin:5px 0;padding:8px;border:1px solid #4e3e49;border-radius:7px;background:#261a21}.issues>article.warning{border-color:#68532e;background:#292114}.issues article header{display:flex;gap:7px}.issues article b{color:#e99aaf;font-size:8px}.issues .warning b{color:#dfbc71}.issues code{color:#c5b8c0;font-size:9px}.issues article>span{display:block;margin-top:3px;color:#8c7f87;font-size:9px}.issues p{margin:2px 0 0;color:#bdb2b8;font-size:10px}
@media(max-width:1100px){.trust-bar{flex-wrap:wrap}.workspace-grid{grid-template-columns:1fr}.editor-card{position:static}textarea{min-height:450px}}@media(max-width:720px){.signature-page{padding:18px 12px}.hero,.truth-lock,.trust-bar{align-items:flex-start;flex-direction:column}.trust-bar label{width:100%}.metrics,.roles{grid-template-columns:repeat(2,1fr)}.checks>div,.binding-panel,.safety-grid{grid-template-columns:1fr}}
</style>
